import Foundation

/// CA chain certificates embedded into every CMS (extracted from the MoldSign middleware output).
/// chainMDTrustCA = mdtrustca root (self-signed), chainMDQSign = MDQSign issuing CA.
enum ChainCerts {
    static let mdTrustCA = Data(base64Encoded: "")!
    static let mdQSign  = Data(base64Encoded: "")!
}
